package com.hospital.platform.iam.infrastructure;

import com.hospital.platform.common.api.ApiResponse; import com.hospital.platform.common.error.ErrorCode; import com.hospital.platform.common.trace.TraceId; import com.hospital.platform.iam.application.PatientTokenService; import com.hospital.platform.iam.application.TokenService; import jakarta.servlet.http.HttpServletResponse; import java.io.IOException; import java.util.Arrays; import java.util.List; import org.springframework.beans.factory.annotation.Value; import org.springframework.context.annotation.Bean; import org.springframework.context.annotation.Configuration; import org.springframework.http.HttpHeaders; import org.springframework.http.MediaType; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.web.SecurityFilterChain; import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter; import org.springframework.stereotype.Component; import org.springframework.web.cors.CorsConfiguration; import org.springframework.web.cors.CorsConfigurationSource; import org.springframework.web.cors.UrlBasedCorsConfigurationSource; import org.springframework.web.filter.OncePerRequestFilter;

@Configuration @EnableWebSecurity @EnableMethodSecurity public class SecurityConfig { private final JwtFilter jwt; private final List<String> origins; public SecurityConfig(JwtFilter jwt,@Value("${hospital.security.cors-origins}") String origins){this.jwt=jwt;this.origins=Arrays.stream(origins.split(",")).map(String::trim).filter(value->!value.isBlank()).toList();}
@Bean SecurityFilterChain security(HttpSecurity http,CorsConfigurationSource corsConfigurationSource)throws Exception{return http.csrf(c->c.disable()).cors(c->c.configurationSource(corsConfigurationSource)).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers(org.springframework.http.HttpMethod.POST,"/api/v1/payment/callback/*","/api/v1/refund/callback/*").permitAll().requestMatchers("/api/v1/auth/login","/api/v1/auth/refresh","/api/v1/patient/auth/**","/api/v1/public/**","/actuator/health","/v3/api-docs/**","/swagger-ui.html","/swagger-ui/**").permitAll().anyRequest().authenticated()).exceptionHandling(e->e.authenticationEntryPoint((request,response,exception)->write(response,401,ErrorCode.AUTH_003)).accessDeniedHandler((request,response,exception)->write(response,403,ErrorCode.FORBIDDEN))).addFilterBefore(jwt,UsernamePasswordAuthenticationFilter.class).build();}
 @Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder(12);} @Bean CorsConfigurationSource corsConfigurationSource(){CorsConfiguration config=new CorsConfiguration();config.setAllowedOrigins(origins);config.setAllowedMethods(List.of("GET","POST","PUT","DELETE","OPTIONS"));config.setAllowedHeaders(List.of("Authorization","Content-Type","X-Trace-Id","Idempotency-Key"));config.setExposedHeaders(List.of("X-Trace-Id"));config.setAllowCredentials(false);UrlBasedCorsConfigurationSource source=new UrlBasedCorsConfigurationSource();source.registerCorsConfiguration("/**",config);return source;} private void write(HttpServletResponse response,int status,ErrorCode code)throws IOException{response.setStatus(status);response.setContentType(MediaType.APPLICATION_JSON_VALUE);new com.fasterxml.jackson.databind.ObjectMapper().writeValue(response.getOutputStream(),ApiResponse.failure(code.code(),code.message(),TraceId.get()));}}
@Component class JwtFilter extends OncePerRequestFilter {private final TokenService tokens;private final PatientTokenService patientTokens;JwtFilter(TokenService tokens,PatientTokenService patientTokens){this.tokens=tokens;this.patientTokens=patientTokens;}protected void doFilterInternal(jakarta.servlet.http.HttpServletRequest request,jakarta.servlet.http.HttpServletResponse response,jakarta.servlet.FilterChain chain)throws jakarta.servlet.ServletException,IOException{String value=request.getHeader(HttpHeaders.AUTHORIZATION);if(value!=null&&value.startsWith("Bearer ")){String raw=value.substring(7);try{var user=tokens.authenticate(raw);var authentication=new UsernamePasswordAuthenticationToken(user,null,user.permissions().stream().map(SimpleGrantedAuthority::new).toList());org.springframework.security.core.context.SecurityContextHolder.getContext().setAuthentication(authentication);}catch(Exception ignored){try{var patient=patientTokens.authenticate(raw);org.springframework.security.core.context.SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(patient,null,List.of()));}catch(Exception ignoredPatient){}}}chain.doFilter(request,response);}}
